SELECT *
FROM sky_department
WHERE deleted = FALSE

    AND department_name LIKE #{departmentNameLike}


    AND enabled = #{enabled}

ORDER BY sort_order ASC, department_id ASC

SELECT COUNT(*) FROM sky_department
WHERE deleted = FALSE AND department_name = #{departmentName}
  AND ((parent_id IS NULL AND #{parentId} IS NULL) OR parent_id = #{parentId})

SELECT COUNT(*) FROM sky_department
WHERE deleted = FALSE AND department_name = #{departmentName} AND department_id <> #{departmentId}
  AND ((parent_id IS NULL AND #{parentId} IS NULL) OR parent_id = #{parentId})
